CREATE SEQUENCE account_tokens_id_seq;
CREATE SEQUENCE accounts_id_seq;
CREATE SEQUENCE admins_id_seq;
CREATE SEQUENCE articles_id_seq;
CREATE SEQUENCE badges_id_seq;
CREATE SEQUENCE categories_id_seq;
CREATE SEQUENCE certificates_id_seq;
CREATE SEQUENCE comments_id_seq;
CREATE SEQUENCE event_registrations_id_seq;
CREATE SEQUENCE event_submissions_id_seq;
CREATE SEQUENCE events_id_seq;
CREATE SEQUENCE member_badges_id_seq;
CREATE SEQUENCE newsletter_campaigns_id_seq;
CREATE SEQUENCE newsletter_subscriptions_id_seq;
CREATE SEQUENCE tags_id_seq;
CREATE SEQUENCE talk_videos_id_seq;
CREATE SEQUENCE user_identities_id_seq;

-- account

CREATE TABLE accounts (
    id bigint DEFAULT nextval('accounts_id_seq'::regclass) NOT NULL,
    email character varying(255) NOT NULL,
    password_hash character varying(255),
    first_name character varying(120) NOT NULL,
    last_name character varying(120) NOT NULL,
    status character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email_verified boolean DEFAULT false NOT NULL,
    provider character varying(20) DEFAULT 'LOCAL'::character varying NOT NULL,
    last_seen_at timestamp with time zone,
    signup_path character varying(255),
    signup_language character varying(20),
    signup_timezone character varying(64),
    signup_source character varying(60),
    CONSTRAINT accounts_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'BANNED'::character varying])::text[]))),
    CONSTRAINT users_pkey PRIMARY KEY (id)
);

CREATE TABLE account_identities (
    id bigint DEFAULT nextval('user_identities_id_seq'::regclass) NOT NULL,
    account_id bigint NOT NULL,
    provider character varying(20) NOT NULL,
    external_id character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_identities_pkey PRIMARY KEY (id),
    CONSTRAINT account_identities_provider_external_id_key UNIQUE (provider, external_id)
);

CREATE TABLE account_tokens (
    id bigint DEFAULT nextval('account_tokens_id_seq'::regclass) NOT NULL,
    account_id bigint NOT NULL,
    purpose character varying(30) NOT NULL,
    token_hash character varying(255) NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_tokens_purpose_check CHECK (((purpose)::text = ANY ((ARRAY['EMAIL_VERIFICATION'::character varying, 'PASSWORD_RESET'::character varying])::text[]))),
    CONSTRAINT account_tokens_pkey PRIMARY KEY (id),
    CONSTRAINT account_tokens_token_hash_key UNIQUE (token_hash)
);

CREATE TABLE admins (
    id bigint DEFAULT nextval('admins_id_seq'::regclass) NOT NULL,
    username character varying(80) NOT NULL,
    password_hash character varying(255) NOT NULL,
    status character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT admins_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying])::text[]))),
    CONSTRAINT admins_pkey PRIMARY KEY (id)
);

CREATE TABLE spring_session (
    primary_id character(36) NOT NULL,
    session_id character(36) NOT NULL,
    creation_time bigint NOT NULL,
    last_access_time bigint NOT NULL,
    max_inactive_interval integer NOT NULL,
    expiry_time bigint NOT NULL,
    principal_name character varying(100),
    CONSTRAINT spring_session_pk PRIMARY KEY (primary_id)
);

CREATE TABLE spring_session_attributes (
    session_primary_id character(36) NOT NULL,
    attribute_name character varying(200) NOT NULL,
    attribute_bytes bytea NOT NULL,
    CONSTRAINT spring_session_attributes_pk PRIMARY KEY (session_primary_id, attribute_name)
);

-- member

CREATE TABLE member_profiles (
    account_id bigint NOT NULL,
    username character varying(50),
    avatar_url character varying(1000),
    bio text,
    location character varying(100),
    social_links jsonb DEFAULT '{}'::jsonb NOT NULL,
    public_bio boolean DEFAULT false NOT NULL,
    public_location boolean DEFAULT false NOT NULL,
    public_links boolean DEFAULT false NOT NULL,
    phone character varying(20),
    country character varying(2),
    situation character varying(30),
    goal character varying(30),
    marketing_consent boolean DEFAULT false NOT NULL,
    onboarded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT member_profiles_pkey PRIMARY KEY (account_id),
    CONSTRAINT member_profiles_username_key UNIQUE (username)
);

CREATE TABLE member_interests (
    account_id bigint NOT NULL,
    category_id bigint NOT NULL,
    CONSTRAINT user_interests_pkey PRIMARY KEY (account_id, category_id)
);

-- newsletter

CREATE TABLE newsletter_subscribers (
    id bigint DEFAULT nextval('newsletter_subscriptions_id_seq'::regclass) NOT NULL,
    account_id bigint,
    status character varying(20) NOT NULL,
    subscribed_at timestamp with time zone DEFAULT now() NOT NULL,
    unsubscribed_at timestamp with time zone,
    token character varying(64) NOT NULL,
    email character varying(255) NOT NULL,
    first_name character varying(120),
    last_name character varying(120),
    CONSTRAINT newsletter_subscriptions_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SUBSCRIBED'::character varying, 'UNSUBSCRIBED'::character varying])::text[]))),
    CONSTRAINT newsletter_subscriptions_pkey PRIMARY KEY (id),
    CONSTRAINT newsletter_subscriptions_token_key UNIQUE (token),
    CONSTRAINT newsletter_subscriptions_user_id_key UNIQUE (account_id)
);

CREATE TABLE newsletter_campaigns (
    id bigint DEFAULT nextval('newsletter_campaigns_id_seq'::regclass) NOT NULL,
    subject character varying(200) NOT NULL,
    message text NOT NULL,
    recipient_count integer NOT NULL,
    sent_at timestamp with time zone NOT NULL,
    CONSTRAINT newsletter_campaigns_pkey PRIMARY KEY (id)
);

-- taxonomy

CREATE TABLE categories (
    id bigint DEFAULT nextval('categories_id_seq'::regclass) NOT NULL,
    name character varying(80) NOT NULL,
    slug character varying(100) NOT NULL,
    description text,
    CONSTRAINT categories_pkey PRIMARY KEY (id),
    CONSTRAINT categories_name_key UNIQUE (name),
    CONSTRAINT categories_slug_key UNIQUE (slug)
);

CREATE TABLE tags (
    id bigint DEFAULT nextval('tags_id_seq'::regclass) NOT NULL,
    name character varying(60) NOT NULL,
    CONSTRAINT tags_pkey PRIMARY KEY (id)
);

-- content

CREATE TABLE articles (
    id bigint DEFAULT nextval('articles_id_seq'::regclass) NOT NULL,
    category_id bigint NOT NULL,
    title character varying(200) NOT NULL,
    description text NOT NULL,
    cover_image character varying(1000) NOT NULL,
    status character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    slug character varying(220) NOT NULL,
    scheduled_at timestamp with time zone,
    published_at timestamp with time zone,
    body jsonb NOT NULL,
    plain_text text,
    reading_minutes integer DEFAULT 1 NOT NULL,
    CONSTRAINT resources_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PUBLISHED'::character varying, 'ARCHIVED'::character varying])::text[]))),
    CONSTRAINT resources_pkey PRIMARY KEY (id)
);

CREATE TABLE article_tags (
    article_id bigint NOT NULL,
    tag_id bigint NOT NULL,
    CONSTRAINT resource_tags_pkey PRIMARY KEY (article_id, tag_id)
);

CREATE TABLE talk_videos (
    id bigint DEFAULT nextval('talk_videos_id_seq'::regclass) NOT NULL,
    title character varying(200) NOT NULL,
    description text NOT NULL,
    guest character varying(160),
    youtube_url character varying(1000) NOT NULL,
    duration_minutes integer,
    published_at timestamp with time zone,
    status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cover_image character varying(1000),
    CONSTRAINT talk_videos_pkey PRIMARY KEY (id)
);

-- event

CREATE TABLE events (
    id bigint DEFAULT nextval('events_id_seq'::regclass) NOT NULL,
    title character varying(200) NOT NULL,
    description text NOT NULL,
    type character varying(30) NOT NULL,
    format character varying(30) NOT NULL,
    start_date timestamp with time zone NOT NULL,
    end_date timestamp with time zone,
    location character varying(200),
    status character varying(20) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cover_image character varying(1000),
    slug character varying(220) NOT NULL,
    scheduled_at timestamp with time zone,
    accepts_submissions boolean DEFAULT false NOT NULL,
    max_team_size integer DEFAULT 1 NOT NULL,
    submission_deadline timestamp with time zone,
    registration_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT events_dates_check CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT events_format_check CHECK (((format)::text = ANY ((ARRAY['ONLINE'::character varying, 'OFFLINE'::character varying, 'HYBRID'::character varying])::text[]))),
    CONSTRAINT events_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'PUBLISHED'::character varying, 'CANCELLED'::character varying, 'COMPLETED'::character varying])::text[]))),
    CONSTRAINT events_team_size_check CHECK (((max_team_size >= 1) AND (max_team_size <= 4))),
    CONSTRAINT events_type_check CHECK (((type)::text = ANY ((ARRAY['BOOTCAMP'::character varying, 'WORKSHOP'::character varying, 'WEBINAR'::character varying, 'CONFERENCE'::character varying, 'HACKATHON'::character varying])::text[]))),
    CONSTRAINT events_pkey PRIMARY KEY (id)
);

CREATE TABLE event_registrations (
    id bigint DEFAULT nextval('event_registrations_id_seq'::regclass) NOT NULL,
    event_id bigint NOT NULL,
    user_id bigint NOT NULL,
    status character varying(20) DEFAULT 'REGISTERED'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_registrations_status_check CHECK (((status)::text = ANY ((ARRAY['REGISTERED'::character varying, 'CANCELLED'::character varying, 'ATTENDED'::character varying, 'ABSENT'::character varying])::text[]))),
    CONSTRAINT event_registrations_pkey PRIMARY KEY (id),
    CONSTRAINT event_registrations_once UNIQUE (event_id, user_id)
);

CREATE TABLE event_submissions (
    id bigint DEFAULT nextval('event_submissions_id_seq'::regclass) NOT NULL,
    event_id bigint NOT NULL,
    owner_id bigint NOT NULL,
    title character varying(200) NOT NULL,
    repository_url character varying(500) NOT NULL,
    demo_url character varying(500),
    description text NOT NULL,
    status character varying(20) DEFAULT 'SUBMITTED'::character varying NOT NULL,
    score integer,
    rank integer,
    review_note text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT event_submissions_rank_check CHECK (((rank IS NULL) OR ((rank >= 1) AND (rank <= 10)))),
    CONSTRAINT event_submissions_score_check CHECK (((score IS NULL) OR ((score >= 0) AND (score <= 100)))),
    CONSTRAINT event_submissions_status_check CHECK (((status)::text = ANY ((ARRAY['SUBMITTED'::character varying, 'UNDER_REVIEW'::character varying, 'ACCEPTED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT event_submissions_pkey PRIMARY KEY (id),
    CONSTRAINT event_submissions_id_event_key UNIQUE (id, event_id)
);

CREATE TABLE event_submission_members (
    submission_id bigint NOT NULL,
    event_id bigint NOT NULL,
    user_id bigint NOT NULL,
    CONSTRAINT event_submission_members_pkey PRIMARY KEY (submission_id, user_id),
    CONSTRAINT event_submission_members_once UNIQUE (event_id, user_id)
);

-- engagement

CREATE TABLE content_views (
    target_type character varying(20) NOT NULL,
    target_id bigint NOT NULL,
    visitor_key character varying(80) NOT NULL,
    viewed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT content_views_target_check CHECK (((target_type)::text = ANY ((ARRAY['ARTICLE'::character varying, 'EVENT'::character varying, 'TALK'::character varying])::text[]))),
    CONSTRAINT content_views_pkey PRIMARY KEY (target_type, target_id, visitor_key)
);

CREATE TABLE content_likes (
    target_type character varying(20) NOT NULL,
    target_id bigint NOT NULL,
    account_id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT content_likes_target_check CHECK (((target_type)::text = ANY ((ARRAY['ARTICLE'::character varying, 'EVENT'::character varying, 'TALK'::character varying])::text[]))),
    CONSTRAINT content_likes_pkey PRIMARY KEY (target_type, target_id, account_id)
);

CREATE TABLE engagement_counters (
    target_type character varying(20) NOT NULL,
    target_id bigint NOT NULL,
    view_count integer DEFAULT 0 NOT NULL,
    like_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT engagement_counters_target_check CHECK (((target_type)::text = ANY ((ARRAY['ARTICLE'::character varying, 'EVENT'::character varying, 'TALK'::character varying])::text[]))),
    CONSTRAINT engagement_counters_pkey PRIMARY KEY (target_type, target_id)
);

CREATE TABLE comments (
    id bigint DEFAULT nextval('comments_id_seq'::regclass) NOT NULL,
    target_id bigint NOT NULL,
    author_id bigint NOT NULL,
    parent_id bigint,
    body character varying(2000) NOT NULL,
    status character varying(20) DEFAULT 'VISIBLE'::character varying NOT NULL,
    report_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    edited_at timestamp with time zone,
    target_type character varying(20) NOT NULL,
    CONSTRAINT comments_status_check CHECK (((status)::text = ANY ((ARRAY['VISIBLE'::character varying, 'HIDDEN'::character varying, 'DELETED'::character varying])::text[]))),
    CONSTRAINT comments_target_check CHECK (((target_type)::text = ANY ((ARRAY['ARTICLE'::character varying, 'EVENT'::character varying, 'TALK'::character varying])::text[]))),
    CONSTRAINT comments_pkey PRIMARY KEY (id)
);

CREATE TABLE comment_reports (
    comment_id bigint NOT NULL,
    reporter_id bigint NOT NULL,
    reason character varying(300),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT comment_reports_pkey PRIMARY KEY (comment_id, reporter_id)
);

-- recognition

CREATE TABLE badges (
    id bigint DEFAULT nextval('badges_id_seq'::regclass) NOT NULL,
    code character varying(60) NOT NULL,
    name character varying(80) NOT NULL,
    description character varying(300) NOT NULL,
    icon character varying(40) DEFAULT 'award'::character varying NOT NULL,
    system boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT badges_pkey PRIMARY KEY (id),
    CONSTRAINT badges_code_key UNIQUE (code)
);

CREATE TABLE member_badges (
    id bigint DEFAULT nextval('member_badges_id_seq'::regclass) NOT NULL,
    badge_id bigint NOT NULL,
    user_id bigint NOT NULL,
    reason character varying(300),
    awarded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT member_badges_pkey PRIMARY KEY (id),
    CONSTRAINT member_badges_once UNIQUE (badge_id, user_id)
);

CREATE TABLE certificates (
    id bigint DEFAULT nextval('certificates_id_seq'::regclass) NOT NULL,
    code character varying(16) NOT NULL,
    user_id bigint NOT NULL,
    event_id bigint,
    kind character varying(20) NOT NULL,
    holder_name character varying(200) NOT NULL,
    title character varying(300) NOT NULL,
    detail character varying(300),
    event_date timestamp with time zone,
    status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    issued_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT certificates_kind_check CHECK (((kind)::text = ANY ((ARRAY['PARTICIPATION'::character varying, 'WINNER'::character varying, 'PODIUM'::character varying, 'AMBASSADOR'::character varying])::text[]))),
    CONSTRAINT certificates_status_check CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ISSUED'::character varying, 'REVOKED'::character varying])::text[]))),
    CONSTRAINT certificates_pkey PRIMARY KEY (id),
    CONSTRAINT certificates_code_key UNIQUE (code),
    CONSTRAINT certificates_once UNIQUE (user_id, event_id, kind)
);

ALTER SEQUENCE account_tokens_id_seq OWNED BY account_tokens.id;
ALTER SEQUENCE accounts_id_seq OWNED BY accounts.id;
