ALTER SEQUENCE event_registrations_id_seq OWNED BY event_registrations.id;
ALTER SEQUENCE event_submissions_id_seq OWNED BY event_submissions.id;
ALTER SEQUENCE events_id_seq OWNED BY events.id;
ALTER SEQUENCE member_badges_id_seq OWNED BY member_badges.id;
ALTER SEQUENCE newsletter_campaigns_id_seq OWNED BY newsletter_campaigns.id;
ALTER SEQUENCE newsletter_subscriptions_id_seq OWNED BY newsletter_subscribers.id;
ALTER SEQUENCE tags_id_seq OWNED BY tags.id;
ALTER SEQUENCE talk_videos_id_seq OWNED BY talk_videos.id;
ALTER SEQUENCE user_identities_id_seq OWNED BY account_identities.id;

ALTER TABLE account_identities ADD CONSTRAINT user_identities_user_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE account_tokens ADD CONSTRAINT account_tokens_account_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE article_tags ADD CONSTRAINT resource_tags_resource_id_fkey FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE;
ALTER TABLE article_tags ADD CONSTRAINT resource_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;
ALTER TABLE articles ADD CONSTRAINT resources_category_id_fkey FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT;
ALTER TABLE certificates ADD CONSTRAINT certificates_event_id_fkey FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL;
ALTER TABLE certificates ADD CONSTRAINT certificates_user_id_fkey FOREIGN KEY (user_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE comment_reports ADD CONSTRAINT comment_reports_comment_id_fkey FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE comment_reports ADD CONSTRAINT comment_reports_reporter_id_fkey FOREIGN KEY (reporter_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE comments ADD CONSTRAINT comments_author_id_fkey FOREIGN KEY (author_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE comments ADD CONSTRAINT comments_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES comments(id) ON DELETE CASCADE;
ALTER TABLE content_likes ADD CONSTRAINT content_likes_account_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE event_registrations ADD CONSTRAINT event_registrations_event_id_fkey FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE;
ALTER TABLE event_registrations ADD CONSTRAINT event_registrations_user_id_fkey FOREIGN KEY (user_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE event_submission_members ADD CONSTRAINT event_submission_members_event_id_fkey FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE;
ALTER TABLE event_submission_members ADD CONSTRAINT event_submission_members_submission_fkey FOREIGN KEY (submission_id, event_id) REFERENCES event_submissions(id, event_id) ON DELETE CASCADE;
ALTER TABLE event_submission_members ADD CONSTRAINT event_submission_members_user_id_fkey FOREIGN KEY (user_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE event_submissions ADD CONSTRAINT event_submissions_event_id_fkey FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE;
ALTER TABLE event_submissions ADD CONSTRAINT event_submissions_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE member_badges ADD CONSTRAINT member_badges_badge_id_fkey FOREIGN KEY (badge_id) REFERENCES badges(id) ON DELETE CASCADE;
ALTER TABLE member_badges ADD CONSTRAINT member_badges_user_id_fkey FOREIGN KEY (user_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE member_interests ADD CONSTRAINT user_interests_category_id_fkey FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE;
ALTER TABLE member_interests ADD CONSTRAINT user_interests_user_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE member_profiles ADD CONSTRAINT member_profiles_account_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE newsletter_subscribers ADD CONSTRAINT newsletter_subscriptions_user_id_fkey FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE;
ALTER TABLE spring_session_attributes ADD CONSTRAINT spring_session_attributes_fk FOREIGN KEY (session_primary_id) REFERENCES spring_session(primary_id) ON DELETE CASCADE;

CREATE INDEX account_identities_account_idx ON account_identities USING btree (account_id);
CREATE INDEX account_tokens_latest_idx ON account_tokens USING btree (account_id, purpose, created_at DESC);
CREATE INDEX accounts_created_at_idx ON accounts USING btree (created_at DESC);
CREATE UNIQUE INDEX accounts_email_lower_key ON accounts USING btree (lower((email)::text));
CREATE INDEX accounts_last_seen_at_idx ON accounts USING btree (last_seen_at);
CREATE UNIQUE INDEX admins_username_lower_key ON admins USING btree (lower((username)::text));
CREATE INDEX article_tags_tag_idx ON article_tags USING btree (tag_id);
CREATE INDEX articles_catalogue_idx ON articles USING btree (status, COALESCE(published_at, created_at) DESC);
CREATE INDEX articles_category_idx ON articles USING btree (category_id);
CREATE INDEX articles_scheduled_at_idx ON articles USING btree (scheduled_at) WHERE (scheduled_at IS NOT NULL);
CREATE INDEX articles_slug_idx ON articles USING btree (slug);
CREATE INDEX articles_status_idx ON articles USING btree (status);
CREATE INDEX certificates_event_idx ON certificates USING btree (event_id);
CREATE INDEX certificates_user_idx ON certificates USING btree (user_id);
CREATE INDEX comment_reports_comment_idx ON comment_reports USING btree (comment_id, created_at);
CREATE INDEX comment_reports_reporter_idx ON comment_reports USING btree (reporter_id);
CREATE INDEX comments_author_idx ON comments USING btree (author_id, created_at);
CREATE INDEX comments_moderation_idx ON comments USING btree (report_count, created_at) WHERE ((status)::text <> 'DELETED'::text);
CREATE INDEX comments_parent_idx ON comments USING btree (parent_id);
CREATE INDEX comments_target_idx ON comments USING btree (target_type, target_id, created_at);
CREATE INDEX content_likes_account_idx ON content_likes USING btree (account_id);
CREATE INDEX event_registrations_user_idx ON event_registrations USING btree (user_id);
CREATE INDEX event_submission_members_user_idx ON event_submission_members USING btree (user_id);
CREATE INDEX event_submissions_event_idx ON event_submissions USING btree (event_id);
CREATE INDEX event_submissions_owner_idx ON event_submissions USING btree (owner_id);
CREATE INDEX events_catalogue_idx ON events USING btree (status, start_date);
CREATE INDEX events_start_date_idx ON events USING btree (start_date DESC);
CREATE INDEX events_status_idx ON events USING btree (status);
CREATE INDEX events_type_idx ON events USING btree (type);
CREATE INDEX idx_event_slug ON events USING btree (slug);
CREATE INDEX idx_events_scheduled_at ON events USING btree (scheduled_at) WHERE (scheduled_at IS NOT NULL);
CREATE INDEX member_badges_user_idx ON member_badges USING btree (user_id);
CREATE INDEX member_interests_category_idx ON member_interests USING btree (category_id);
CREATE INDEX member_profiles_country_idx ON member_profiles USING btree (country);
CREATE INDEX member_profiles_onboarded_at_idx ON member_profiles USING btree (onboarded_at);
CREATE UNIQUE INDEX newsletter_subscribers_email_key ON newsletter_subscribers USING btree (lower((email)::text));
CREATE INDEX newsletter_subscribers_status_idx ON newsletter_subscribers USING btree (status);
CREATE INDEX newsletter_subscribers_subscribed_at_idx ON newsletter_subscribers USING btree (subscribed_at);
CREATE UNIQUE INDEX spring_session_ix1 ON spring_session USING btree (session_id);
CREATE INDEX spring_session_ix2 ON spring_session USING btree (expiry_time);
CREATE INDEX spring_session_ix3 ON spring_session USING btree (principal_name);
CREATE UNIQUE INDEX tags_name_unique ON tags USING btree (lower((name)::text));
CREATE INDEX idx_talk_videos_status_published_at ON talk_videos USING btree (status, published_at DESC NULLS LAST);
